/// Lookup by "city, country", e.g. timezone_of("Ashdod, Israel").
pub fn timezone_of(key: &str) -> Option<&'static str> {
    let key = key.to_lowercase();
    CITY_TIMEZONES
        .binary_search_by(|(k, _)| (*k).cmp(key.as_str()))
        .ok()
        .map(|i| CITY_TIMEZONES[i].1)
}
